import type { Project } from "./model.js";
import type { Op } from "./ops.js";
import { applyOps } from "./ops.js";

/**
 * Pre-flight validation for ops generated by untrusted sources (LLM, rules,
 * imported scripts). Structural shape → referential integrity → dry-run apply
 * on a throwaway copy of the project. Never mutates the real project.
 */

/** Ops an AI assistant may emit. Mutations beyond this need human action. */
export const AI_ALLOWED_OPS: ReadonlySet<string> = new Set([
  "asset.set",
  "track.add", "track.set",
  "clip.add", "clip.remove", "clip.replace", "clip.move", "clip.trim",
  "clip.split", "clip.setSpeed", "clip.set",
  "effect.add", "effect.remove", "effect.setParam",
  "scene.upsert",
  "element.add", "element.remove", "element.set",
  "key.set", "key.remove", "key.toggle",
  "project.set",
]);

export interface ValidateOptions {
  /** Whitelist of permitted op types. Default: AI_ALLOWED_OPS. */
  allowedTypes?: ReadonlySet<string>;
  /** Max ops in one batch. Default 64. */
  maxOps?: number;
}

export interface ValidationIssue {
  index: number;
  op: string;
  message: string;
}

export interface ValidationResult {
  ok: boolean;
  issues: ValidationIssue[];
}

const isObj = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null;
const isStr = (v: unknown): v is string => typeof v === "string" && v.length > 0;
const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);

/** Cheap structural check of required fields per op type. */
function shapeIssue(op: Record<string, unknown>): string | null {
  const id = (k: string) => isStr(op[k]);
  const clipOk = isObj(op["clip"]) && isStr((op["clip"] as Record<string, unknown>)["id"]) &&
    isNum((op["clip"] as Record<string, unknown>)["duration"]);
  switch (op["type"]) {
    case "asset.add": return isObj(op["asset"]) && isStr((op["asset"] as Record<string, unknown>)["id"]) ? null : "asset must have an id";
    case "asset.remove": case "asset.set": return id("assetId") ? null : "missing assetId";
    case "project.set": return isObj(op["patch"]) ? null : "missing patch";
    case "track.add": return isObj(op["track"]) && isStr((op["track"] as Record<string, unknown>)["id"]) ? null : "track must have an id";
    case "track.remove": case "track.set": return id("trackId") ? null : "missing trackId";
    case "clip.add": return id("trackId") ? (clipOk ? null : "clip missing id/duration") : "missing trackId";
    case "clip.remove": case "clip.replace": case "clip.move": case "clip.trim":
    case "clip.split": case "clip.setSpeed": case "clip.set":
    case "effect.add": case "effect.remove": case "effect.setParam":
    case "key.set": case "key.remove": case "key.toggle":
      return id("clipId") ? null : "missing clipId";
    case "scene.upsert": case "scene.remove": return id("sceneId") || isObj(op["scene"]) ? null : "missing scene/sceneId";
    case "element.add": case "element.remove": case "element.set": return id("sceneId") ? null : "missing sceneId";
    default: return `unknown op type`;
  }
}

/** Referential integrity: ids must exist now or be created earlier in the batch. */
function refIssue(project: Project, op: Op, created: { assets: Set<string>; tracks: Set<string>; clips: Set<string>; scenes: Set<string> }): string | null {
  const assetOk = (id: unknown) => typeof id === "string" && (id in project.assets || created.assets.has(id));
  const trackOk = (id: unknown) => typeof id === "string" && (project.tracks.some((t) => t.id === id) || created.tracks.has(id));
  const clipOk = (id: unknown) => typeof id === "string" && (findClipId(project, id) || created.clips.has(id));
  const sceneOk = (id: unknown) => typeof id === "string" && (id in project.scenes || created.scenes.has(id));
  switch (op.type) {
    case "asset.add": created.assets.add(op.asset.id); return null;
    case "asset.remove": case "asset.set": return assetOk(op.assetId) ? null : `unknown asset ${op.assetId}`;
    case "track.add": created.tracks.add(op.track.id); return null;
    case "track.remove": case "track.set": return trackOk(op.trackId) ? null : `unknown track ${op.trackId}`;
    case "clip.add": {
      if (!trackOk(op.trackId)) return `unknown track ${op.trackId}`;
      const c = op.clip;
      if ("assetId" in c && !assetOk(c.assetId)) return `unknown asset ${c.assetId}`;
      if (c.kind === "scene" && !sceneOk(c.sceneId)) return `unknown scene ${c.sceneId}`;
      created.clips.add(c.id);
      return null;
    }
    case "clip.remove": case "clip.replace": case "clip.move": case "clip.trim":
    case "clip.split": case "clip.setSpeed": case "clip.set":
    case "effect.add": case "effect.remove": case "effect.setParam":
    case "key.set": case "key.remove": case "key.toggle":
      return clipOk(op.clipId) ? null : `unknown clip ${op.clipId}`;
    case "scene.upsert": created.scenes.add(op.scene.id); return null;
    case "scene.remove": return sceneOk(op.sceneId) ? null : `unknown scene ${op.sceneId}`;
    case "element.add": case "element.remove": case "element.set":
      return sceneOk(op.sceneId) ? null : `unknown scene ${op.sceneId}`;
    default: return null;
  }
}

function findClipId(p: Project, id: string): boolean {
  return p.tracks.some((t) => t.clips.some((c) => c.id === id));
}

export function validateOps(
  project: Project,
  ops: unknown[],
  opts: ValidateOptions = {},
): ValidationResult {
  const allowed = opts.allowedTypes ?? AI_ALLOWED_OPS;
  const maxOps = opts.maxOps ?? 64;
  const issues: ValidationIssue[] = [];

  if (ops.length === 0) issues.push({ index: -1, op: "-", message: "empty op batch" });
  if (ops.length > maxOps) {
    issues.push({ index: -1, op: "-", message: `batch too large: ${ops.length} ops (max ${maxOps})` });
    return { ok: false, issues };
  }

  const created = { assets: new Set<string>(), tracks: new Set<string>(), clips: new Set<string>(), scenes: new Set<string>() };
  for (let i = 0; i < ops.length; i++) {
    const raw = ops[i];
    const tag = isObj(raw) && typeof raw["type"] === "string" ? String(raw["type"]) : `ops[${i}]`;
    if (!isObj(raw) || !isStr(raw["type"])) {
      issues.push({ index: i, op: tag, message: "not an op object (missing type)" });
      continue;
    }
    if (!allowed.has(raw["type"])) {
      issues.push({ index: i, op: tag, message: `op type not allowed` });
      continue;
    }
    const shape = shapeIssue(raw);
    if (shape) { issues.push({ index: i, op: tag, message: shape }); continue; }
    const ref = refIssue(project, raw as Op, created);
    if (ref) issues.push({ index: i, op: tag, message: ref });
  }
  if (issues.length) return { ok: false, issues };

  // semantic dry-run on a detached copy (durations, ranges, scene refs…)
  try {
    applyOps(project, ops as Op[]);
  } catch (e) {
    issues.push({ index: -1, op: "-", message: `dry-run failed: ${e instanceof Error ? e.message : String(e)}` });
  }
  return { ok: issues.length === 0, issues };
}
